('advanced-native-988', '["phrase"]'::jsonb, '{"advanced-native-988-v1-audio":{"type":"mc","answers":["Online booking could simplify the process, but some visitors still need another access route."],"options":["The online form has been tested successfully with every regular visitor.","The proposal was designed to make booking more complicated.","Online booking could simplify the process, but some visitors still need another access route.","The telephone option has already been removed without affecting visitors."]},"advanced-native-988-v2-reply":{"type":"mc","answers":["In theory, online-only booking is simpler, but it would leave some visitors without reliable access.","The proposed simplification does not meet everyone’s actual access needs.","We need another route for people whose connection is unreliable.","Some regular visitors cannot rely on an internet connection."],"options":["In theory, online-only booking is simpler, but it would leave some visitors without reliable access.","The proposed simplification does not meet everyone’s actual access needs.","We need another route for people whose connection is unreliable.","Some regular visitors cannot rely on an internet connection."]},"advanced-native-988-v1-scene":{"type":"mc","answers":["The timetable works in theory, but the required break interrupts the two-hour rehearsal."],"options":["The venue has already waived the required break.","The rehearsal was planned with that break included from the start.","The timetable works in theory, but the required break interrupts the two-hour rehearsal."]},"advanced-native-988-v1-contrast":{"type":"mc","answers":["Repeating the same unqualified claim without showing a contrast."],"options":["Distinguishing a proposal from the conditions in which it must operate.","Naming a predicted benefit and an actual obstacle.","Repeating the same unqualified claim without showing a contrast."]},"advanced-native-988-v1-branch":{"type":"mc","answers":["It is simpler in theory, but we